import numpy as np

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    scores = np.where(remaining >= 0, remaining, -np.inf)
    if np.any(remaining >= 0):
        max_cap = np.max(bins)
        scores = np.where((bins == max_cap) & (remaining >= 0), scores * 0.1, scores)
    else:
        scores = np.zeros_like(bins)
    return scores
```

